//! Disposable benchmark of cloning admitted synchronous Blocks.
#[path = "../tests/support/oop.rs"] mod oop;
use birnam_abi::size;
use birnam_artifact_codec::portable_program::{encode,NodeSpec,ProgramSpec,StatementSpec};
unsafe extern "C" {fn clock_gettime_nsec_np(clock:u32)->u64;}
fn main(){
 let h=oop::bootstrap();let q=h.scope();let gc=h.named(b"GC").unwrap();let nil=h.named(b"nil").unwrap();
 let clone=q.keep(h.intern(b"clone").unwrap()).unwrap();
 q.call(gc,b"automaticCollection:",&[size(0).unwrap()]).unwrap();
 for count in [0,1,8,64] {
  let names:Vec<_>=(0..count).map(|i|format!("c{i}")).collect();let captures:Vec<_>=names.iter().map(|s|s.as_bytes()).collect();
  let nodes=[if count==0 {NodeSpec::Nil}else{NodeSpec::LexicalRead(0)}];
  let encoded=encode(ProgramSpec{parameters:&[],captures:&captures,lets:&[],statements:&[StatementSpec::Expression{root_node:0}],nodes:&nodes}).unwrap();
  let bytes=q.call(h.named(b"Bytes").unwrap(),b"fromBytes:",&[q.byte_values(&encoded).unwrap()]).unwrap();
  let code=q.call(h.named(b"CodeObject").unwrap(),b"fromCanonicalBytes:",&[bytes]).unwrap();
  let values:Vec<_>=(0..count).map(|i|q.word(i+99).unwrap()).collect();
  let mut vector=q.call(h.named(b"Vector").unwrap(),b"new",&[]).unwrap();
  for &v in &values {vector=q.call(vector,b"add:",&[v]).unwrap();}
  let block=q.call(h.named(b"Codegen").unwrap(),b"materializeSynchronous:captures:",&[code,vector]).unwrap();
  let calls=4096;
  for sample in 0..7 {
   q.call(gc,b"collectPrecisely",&[]).unwrap();let mut last=nil;
   let start=unsafe{clock_gettime_nsec_np(16)};
   for _ in 0..calls {last=unsafe{h.id.send(block,clone,&[]).unwrap()};}
   let elapsed=unsafe{clock_gettime_nsec_np(16)}-start;
   q.keep(last).unwrap();assert_ne!(last,block);
   for (i,&v) in values.iter().enumerate(){assert_eq!(q.call(last,b"captureWordAt:",&[size(i).unwrap()]).unwrap(),v);}
   assert_eq!(q.call(last,b"value",&[]).unwrap(),values.first().copied().unwrap_or(nil));
   println!("{count} {sample} {calls} {elapsed}");
  }
 }
}

